    function createTrashIcon() {
        const icon = document.createElement('img');
        icon.src = 'data:image/png;base64,';
        icon.alt = ''; icon.width = 16; icon.height = 16;
        Object.assign(icon.style, { display: 'block', maxWidth: 'none', margin: '0', padding: '0' });
        return icon;
    }

    function restoreAutoScanJob() {
        try {
            const job = JSON.parse(scannerStorage.getItem('autoScanJob'));
            if (!job || !Array.isArray(job.players) || !job.players.length ||
                !job.players.every(player => normalizePlayerId(player.id) === player.id && typeof player.name === 'string') ||
                new Set(job.players.map(player => player.id)).size !== job.players.length ||
                !Array.isArray(job.selectedIds) || !job.selectedIds.length ||
                !job.selectedIds.every(id => pictosById.has(id)) ||
                !Number.isInteger(job.index) || job.index < 0 || job.index > job.players.length ||
                !Number.isInteger(job.success) || job.success < 0 || job.success > job.index ||
                !Array.isArray(job.errors) || !job.errors.every(error => typeof error === 'string') ||
                !['running', 'paused', 'completed', 'stopped'].includes(job.status)) return null;
            if (job.scanId && !getSavedScan(job.scanId)) return null;
            job.doneIds ??= job.players.slice(0, job.index).map(player => player.id);
            if (!Array.isArray(job.doneIds) || job.doneIds.length !== job.index ||
                new Set(job.doneIds).size !== job.doneIds.length ||
                !job.doneIds.every(id => job.players.some(player => player.id === id))) return null;
            if (job.status === 'running') {
                job.status = 'paused';
                job.message = 'Le scan a été interrompu. Clique sur Reprendre pour continuer.';
            }
            return job;
        } catch (_) { return null; }
    }

    function autoScanBusy() {
        return !!autoScanJob && ['running', 'paused'].includes(autoScanJob.status);
    }

    function allowDataChange() {
        if (!autoScanBusy()) return true;
        alert('Attends la fin du scan avant de modifier les pictos.');
        return false;
    }

    function persistAutoScanJob() {
        scannerStorage.setItem('autoScanJob', JSON.stringify(autoScanJob));
        const scan = autoScanJob ? getSavedScan(autoScanJob.scanId) : null;
        if (scan) {
            scan.status = autoScanJob.status;
            scan.processed = autoScanJob.index;
            scan.errors = [...autoScanJob.errors];
            if (scan.status === 'completed' && !scan.completedAt) scan.completedAt = new Date().toISOString();
            persistScanCollection();
        }
    }

    function autoScanIsCurrent(job, token) {
        return job === autoScanJob && job.status === 'running' && token === autoScanToken;
    }

    function autoScanError(message, options = {}) {
        return Object.assign(new Error(message), options);
    }

    async function requestAutoScanPictos(player, job, token) {
        for (let attempt = 0; attempt < 2; attempt++) {
            if (!autoScanIsCurrent(job, token)) throw autoScanError('Scan interrompu.');
            const controller = new AbortController();
            autoScanControllers.add(controller);
            let timedOut = false;
            const timer = setTimeout(() => { timedOut = true; controller.abort(); }, 20000);
            try {
                const base = new URL(document.querySelector('base[href]')?.getAttribute('href') || '/', location.href);
                const url = new URL(`${base.pathname.replace(/\/+$/, '')}/rest/v1/user/soul/distinctions/${player.id}/soul`, location.origin);
                const response = await fetch(url.href, {
                    method: 'GET', credentials: 'same-origin', cache: 'no-store',
                    headers: { Accept: 'application/json' }, signal: controller.signal,
                });
                if (response.status === 401 || response.status === 403 ||
                    ['reset', 'navigate', 'reload'].includes(response.headers.get('X-AJAX-Control'))) {
                    throw autoScanError('Session MyHordes interrompue. Reconnecte-toi puis reprends le scan.', { pause: true });
                }
                if (response.status === 429) throw autoScanError('Le serveur limite les requêtes. Attends avant de reprendre.', { pause: true });
                if (response.status === 404) throw autoScanError('Joueur introuvable.');
                if (!response.ok) throw autoScanError(`Chargement impossible (${response.status}).`, { retryable: response.status >= 500 });
                if (!/json/i.test(response.headers.get('Content-Type') || '')) {
                    throw autoScanError('Réponse inattendue du jeu. Vérifie ta connexion puis reprends le scan.', { pause: true });
                }
                const data = await response.json();
                if (!data || !Array.isArray(data.pictos)) throw autoScanError('Les pictos reçus ne sont pas lisibles.');
                return data;
            } catch (error) {
                if (!autoScanIsCurrent(job, token)) throw error;
                if (timedOut) error = autoScanError('Le serveur n’a pas répondu à temps.', { retryable: true });
                else if (error instanceof TypeError) error = autoScanError('Connexion au jeu impossible.', { retryable: true });
                if (error.pause || !error.retryable || attempt === 1) throw error;
            } finally {
                clearTimeout(timer);
                autoScanControllers.delete(controller);
            }
            await new Promise(resolve => setTimeout(resolve, autoScanDelay));
        }
    }

    function parseAutoScanPictos(data, selectedIds) {
        const counts = new Map();
        for (const picto of data.pictos) {
            if (!picto || typeof picto.icon !== 'string') throw autoScanError('Une donnée de picto est incomplète.');
            let url;
            try { url = new URL(picto.icon, location.origin); }
            catch (_) { throw autoScanError('Une icône de picto est illisible.'); }
            const id = url.pathname.split('/').pop().match(/^(r_[^.]+)(?:\.[^/]*)?\.gif$/)?.[1];
            if (!id || !pictosById.has(id)) continue;
            if (!(typeof picto.count === 'number' || typeof picto.count === 'string' && /^\d+$/.test(picto.count)) ||
                !Number.isSafeInteger(Number(picto.count)) || Number(picto.count) < 0 || counts.has(id)) {
                throw autoScanError('Une valeur de picto est illisible.');
            }
            counts.set(id, Number(picto.count));
        }
        return selectedIds.map(pictoId => ({ pictoId, value: String(counts.get(pictoId) || 0) }));
    }

    async function runAutoScan(job, token) {
        const done = new Set(job.doneIds);
        let nextIndex = 0;
        const takeNext = () => {
            while (nextIndex < job.players.length && done.has(job.players[nextIndex].id)) nextIndex++;
            return nextIndex < job.players.length ? nextIndex++ : null;
        };
        const worker = async () => {
            while (autoScanIsCurrent(job, token)) {
                const index = takeNext();
                if (index === null) return;
                const player = job.players[index];
                try {
                    const data = await requestAutoScanPictos(player, job, token);
                    if (!autoScanIsCurrent(job, token)) return;
                    const values = parseAutoScanPictos(data, job.selectedIds);
                    recordPlayerResult(player.id, player.name, values, job.scanId, index + 1);
                    job.success++;
                } catch (error) {
                    if (!autoScanIsCurrent(job, token)) return;
                    if (error.pause) { pauseAutoScan(error.message); return; }
                    job.errors.push(`${player.name} : ${error.message || 'Scan impossible.'}`);
                }
                done.add(player.id);
                job.doneIds = [...done];
                job.index = done.size;
                persistAutoScanJob(); updateAutoScanPanel();
                await new Promise(resolve => setTimeout(resolve, autoScanDelay));
            }
        };
        try {
            const outcomes = await Promise.allSettled(Array.from({ length: Math.min(autoScanConcurrency, job.players.length) }, worker));
            if (!autoScanIsCurrent(job, token)) return;
            const failure = outcomes.find(outcome => outcome.status === 'rejected');
            if (failure) throw failure.reason;
            job.status = 'completed';
            const panel = document.getElementById('pictos-scans-panel');
            const overview = document.getElementById('pictos-scan-overview');
            completedScanNoticeId = panel && panel.style.display !== 'none' && overview?.style.display !== 'none' ? job.scanId : null;
            persistAutoScanJob(); updateAutoScanPanel();
            refreshAutoScanResults();
        } catch (error) {
            if (!autoScanIsCurrent(job, token)) return;
            pauseAutoScan('Le scan s’est interrompu. Les résultats déjà enregistrés sont conservés.');
            console.error('Pictos Scanner :', error);
        }
    }

    function startAutoScan() {
        if (autoScanJob?.status === 'running' || forumImportController) return;
        if (autoScanJob?.status !== 'paused') {
            const input = document.getElementById('pictos-scan-name');
            const name = input.value.trim();
            if (!name) {
                showAutoScanValidation('Renseigne un nom pour lancer le scan.');
                input.focus?.();
                return;
            }
            if (!playerRoster.length) {
                showAutoScanValidation('Ajoute au moins un joueur dans l’onglet Joueurs.');
                return;
            }
            saveSettings();
            const selectedIds = selectedPictoIds();
            if (!selectedIds.length) {
                showAutoScanValidation('Sélectionne au moins un picto dans l’onglet Sélection.');
                return;
            }
            const scan = createSavedScan(name, playerRoster, selectedIds);
            input.value = '';
            autoScanJob = { scanId: scan.id, players: scan.players.map(player => ({ ...player })),
                selectedIds, doneIds: [], index: 0, success: 0, errors: [], status: 'running', message: '' };
        }
        completedScanNoticeId = null;
        autoScanJob.status = 'running';
        autoScanJob.message = '';
        const token = ++autoScanToken;
        persistAutoScanJob(); updateAutoScanPanel();
        void runAutoScan(autoScanJob, token);
    }

    function pauseAutoScan(message = '') {
        if (autoScanJob?.status !== 'running') return;
        autoScanJob.status = 'paused';
        autoScanJob.message = typeof message === 'string' ? message : '';
        autoScanToken++;
        autoScanControllers.forEach(controller => controller.abort());
        autoScanControllers.clear();
        persistAutoScanJob(); updateAutoScanPanel();
        refreshAutoScanResults();
    }

    function stopAutoScan() {
        if (!autoScanBusy()) return;
        autoScanJob.status = 'stopped';
        autoScanJob.message = '';
        autoScanToken++;
        autoScanControllers.forEach(controller => controller.abort());
        autoScanControllers.clear();
        persistAutoScanJob(); updateAutoScanPanel();
        refreshAutoScanResults();
    }

    function refreshAutoScanResults() {
        const host = document.getElementById('pictos-auto-results-host');
        if (host && viewedScanId && host.style.display !== 'none') {
            host.textContent = '';
            host.appendChild(createResultsPanel(viewedScanId));
        }
    }

    function showAutoScanValidation(message) {
        completedScanNoticeId = null;
        const status = document.getElementById('pictos-auto-status');
        status.textContent = message; status.hidden = false;
        document.getElementById('pictos-auto-feedback').hidden = false;
        document.getElementById('pictos-auto-progress').hidden = true;
    }

    function updateAutoScanPanel() {
        const playerList = document.getElementById('pictos-player-list');
        if (playerList && playerList.dataset.scanBusy !== String(autoScanBusy())) updatePlayersPanel();
        const start = document.getElementById('pictos-auto-start');
        if (!start) return;
        const name = document.getElementById('pictos-scan-name');
        const status = document.getElementById('pictos-auto-status');
        const errors = document.getElementById('pictos-auto-errors');
        const feedback = document.getElementById('pictos-auto-feedback');
        const progressBar = document.getElementById('pictos-auto-progress');
        const progressFill = progressBar.firstElementChild;
        name.disabled = autoScanBusy();
        start.disabled = autoScanJob?.status === 'running' || !!forumImportController ||
            autoScanJob?.status !== 'paused' && (!playerRoster.length || !name.value.trim());
        start.textContent = autoScanJob?.status === 'paused' ? 'Reprendre' : 'Scanner';
        start.style.opacity = start.disabled ? '0.5' : '1';
        errors.textContent = '';
        const showCompletion = autoScanJob?.status === 'completed' && completedScanNoticeId === autoScanJob.scanId;
        const showProgress = autoScanBusy() || showCompletion;
        feedback.hidden = !showProgress;
        progressBar.hidden = !showProgress;
        status.textContent = '';
        status.hidden = !showProgress || autoScanJob?.status === 'running';
        progressBar.setAttribute('aria-valuemax', String(autoScanJob?.players.length || 1));
        progressBar.setAttribute('aria-valuenow', String(autoScanJob?.index || 0));
        progressBar.setAttribute('aria-valuetext', autoScanJob ? `${autoScanJob.index}/${autoScanJob.players.length} joueurs traités` : '');
        progressFill.style.width = autoScanJob ? `${100 * autoScanJob.index / autoScanJob.players.length}%` : '0%';
        if (autoScanJob && showProgress) {
            const job = autoScanJob;
            const progress = `${job.index}/${job.players.length}`;
            if (job.status === 'paused') status.textContent = `En pause — ${progress}. ${job.message || ''}`.trim();
            else if (showCompletion) status.textContent = `Terminé — ${job.success}/${job.players.length} joueurs scannés.`;
            job.errors.forEach(message => {
                const item = document.createElement('li'); item.textContent = message; errors.appendChild(item);
            });
        }
        errors.hidden = !showProgress || !errors.children.length;
        updateScanHistory();
    }

    function viewSavedScan(id) {
        if (!getSavedScan(id)) return;
        const panel = document.getElementById('pictos-scans-panel');
        if (!panel) return;
        if (panel.style.display === 'none') document.querySelectorAll('.pictos-scanner-window .tab-link')[2]?.click();
        viewedScanId = id;
        scanCollection.selectedId = id; persistScanCollection();
        document.getElementById('pictos-scan-overview').style.display = 'none';
        document.getElementById('pictos-auto-results-host').style.display = 'flex';
        refreshAutoScanResults();
    }

    function showScanOverview() {
        viewedScanId = null;
        const overview = document.getElementById('pictos-scan-overview');
        const host = document.getElementById('pictos-auto-results-host');
        if (overview) overview.style.display = 'block';
        if (host) { host.style.display = 'none'; host.textContent = ''; }
        updateScanHistory();
    }

    const expandedScanPreviews = new Set();
    const scanHistoryViews = new WeakMap();

    function createScanHistoryCard(scan) {
        const card = document.createElement('div'); card.className = 'hps-scan-card';
        const head = document.createElement('div'); head.className = 'hps-scan-head';
        const row = document.createElement('button');
        row.type = 'button'; row.dataset.scanId = scan.id;
        row.className = 'hps-scan-row pictos-view-scan';
        row.addEventListener('click', () => viewSavedScan(scan.id));
        const title = document.createElement('strong');
        const detail = document.createElement('small');
        row.append(title, detail); head.appendChild(row);
        const actions = document.createElement('div'); actions.className = 'hps-scan-preview-actions';
        const preview = document.createElement('div'); preview.className = 'hps-scan-preview';
        preview.dataset.scanId = scan.id;
        preview.hidden = !expandedScanPreviews.has(scan.id);
        const toggle = document.createElement('button'); toggle.type = 'button';
        toggle.className = 'hps-preview-toggle';
        toggle.title = 'Afficher les joueurs et les pictos du scan';
        toggle.setAttribute('aria-label', toggle.title);
        const iconSlot = document.createElement('span'); iconSlot.className = 'hps-preview-icon';
        iconSlot.style.width = '15px';
        const icon = document.createElement('img'); icon.src = scanPreviewIcons.pictos; icon.alt = '';
        icon.style.transform = 'translateX(-1px)'; iconSlot.appendChild(icon);
        toggle.appendChild(iconSlot);
        toggle.setAttribute('aria-expanded', String(!preview.hidden));
        const populate = () => {
            if (preview.childNodes.length) return;
            const players = document.createElement('div'); players.className = 'hps-preview-list';
            players.dataset.previewType = 'players';
            players.setAttribute('role', 'group'); players.setAttribute('aria-label', 'Joueurs du scan');
            scan.players.forEach(player => players.appendChild(createPlayerTag(player)));
            const pictos = document.createElement('div'); pictos.className = 'hps-preview-list';
            pictos.dataset.previewType = 'pictos';
            pictos.setAttribute('role', 'group'); pictos.setAttribute('aria-label', 'Pictos du scan');
            scan.selectedIds.forEach(id => {
                const picto = pictosById.get(id);
                if (picto) pictos.appendChild(createPictoImage(picto));
            });
            preview.append(players, pictos);
        };
        if (!preview.hidden) populate();
        toggle.addEventListener('click', () => {
            preview.hidden = !preview.hidden;
            toggle.setAttribute('aria-expanded', String(!preview.hidden));
            if (preview.hidden) expandedScanPreviews.delete(scan.id);
            else { expandedScanPreviews.add(scan.id); populate(); }
        });
        const remove = document.createElement('button'); remove.type = 'button';
        remove.className = 'hps-icon-button pictos-delete-scan'; remove.dataset.scanId = scan.id;
        remove.title = `Supprimer le scan « ${scan.name} »`;
        remove.setAttribute('aria-label', remove.title); remove.appendChild(createTrashIcon());
        remove.addEventListener('click', () => deleteSavedScan(scan.id));
        actions.style.alignItems = 'center'; actions.append(toggle, remove);
        head.appendChild(actions); card.append(head, preview);
        return { card, title, detail, preview, toggle, remove, signature: null };
    }

    function updateScanHistory() {
        const history = document.getElementById('pictos-scan-history');
        if (!history) return;
        const deleteAll = document.getElementById('pictos-delete-all-scans');
        deleteAll.disabled = !scanCollection.scans.length || autoScanJob?.status === 'running';
        deleteAll.style.opacity = deleteAll.disabled ? '0.5' : '1';
        deleteAll.title = autoScanJob?.status === 'running' ? 'Attends la fin du scan avant de tout supprimer.' : 'Supprimer tous les scans';
        let cards = scanHistoryViews.get(history);
        if (!cards) { cards = new Map(); scanHistoryViews.set(history, cards); }
        if (!scanCollection.scans.length) {
            if (history.textContent !== 'Aucun scan enregistré.') history.textContent = 'Aucun scan enregistré.';
            cards.clear();
            return;
        }
        if (!cards.size) history.textContent = '';
        const ids = new Set(scanCollection.scans.map(scan => scan.id));
        for (const [id, entry] of cards) {
            if (!ids.has(id)) { entry.card.remove(); cards.delete(id); }
        }
        [...scanCollection.scans].reverse().forEach((scan, index) => {
            let entry = cards.get(scan.id);
            if (!entry) { entry = createScanHistoryCard(scan); cards.set(scan.id, entry); }
            entry.remove.disabled = autoScanJob?.status === 'running' && autoScanJob.scanId === scan.id;
            const count = Object.keys(scan.results).length;
            const signature = JSON.stringify([scan.name, scan.status, count, scan.players.length]);
            if (entry.signature !== signature) {
                entry.signature = signature;
                if (entry.title.textContent !== scan.name) entry.title.textContent = scan.name;
                const status = { running: 'En cours', paused: 'En pause', stopped: 'Arrêté', completed: 'Terminé', manual: 'Manuel' }[scan.status] || '';
                const date = scan.createdAt ? new Date(scan.createdAt).toLocaleString('fr-FR') + ' · ' : '';
                entry.detail.textContent = `${date}${count}/${scan.players.length} joueurs · ${status}`;
            }
            const previewId = `pictos-preview-${index}`;
            if (entry.preview.id !== previewId) {
                entry.preview.id = previewId; entry.toggle.setAttribute('aria-controls', previewId);
            }
            if (history.children[index] !== entry.card) history.insertBefore(entry.card, history.children[index] || null);
        });
    }

    function createAutoScanPanel() {
        const panel = document.createElement('div');
        panel.id = 'pictos-scans-panel'; panel.className = 'hps-panel';
        panel.style.color = colors.lightGold;
        panel.style.fontSize = '12px';
        const overview = document.createElement('div'); overview.id = 'pictos-scan-overview';
        const nameHeading = document.createElement('h5');
        const label = document.createElement('label');
        label.htmlFor = 'pictos-scan-name';
        label.textContent = 'Nom du scan';
        label.style.font = 'inherit'; label.style.color = 'inherit'; nameHeading.appendChild(label);
        const input = document.createElement('input');
        input.id = 'pictos-scan-name'; input.type = 'text'; input.maxLength = 100;
        input.value = '';
        input.required = true;
        input.addEventListener('input', updateAutoScanPanel);
        input.style.width = '100%';
        const help = document.createElement('p');
        help.textContent = 'Chaque nouveau scan est enregistré séparément, avec les joueurs et les pictos choisis.';
        help.className = 'hps-import-help';
        const controls = document.createElement('div');
        controls.className = 'hps-scan-controls';
        const start = createCustomButton('pictos-auto-start', 'Scanner', startAutoScan);
        start.type = 'button'; start.style.margin = '0'; controls.appendChild(start);
        const status = document.createElement('p');
        status.id = 'pictos-auto-status'; status.style.margin = '0';
        status.setAttribute('role', 'status'); status.setAttribute('aria-live', 'polite');
        const progress = document.createElement('div');
        progress.id = 'pictos-auto-progress'; progress.className = 'hps-progress'; progress.hidden = true;
        progress.setAttribute('role', 'progressbar'); progress.setAttribute('aria-label', 'Progression du scan');
        progress.setAttribute('aria-valuemin', '0');
        const progressFill = document.createElement('div'); progressFill.className = 'hps-progress-fill';
        progress.appendChild(progressFill);
        const feedback = document.createElement('div');
        feedback.id = 'pictos-auto-feedback'; feedback.className = 'hps-scan-feedback'; feedback.hidden = true;
        feedback.append(status, progress); controls.appendChild(feedback);
        const errors = document.createElement('ul');
        errors.id = 'pictos-auto-errors'; errors.style.paddingLeft = '18px'; errors.style.margin = '10px 0 0'; errors.hidden = true;
        const historyTitle = document.createElement('h5'); historyTitle.textContent = 'Scans enregistrés';
        Object.assign(historyTitle.style, { margin: '0', flex: '1', minWidth: '0' });
        const deleteAll = createCustomButton('pictos-delete-all-scans', 'Tout supprimer', deleteAllSavedScans);
        deleteAll.style.margin = '0';
        const historyHeading = document.createElement('div');
        Object.assign(historyHeading.style, { display: 'flex', alignItems: 'center', gap: '12px', margin: '22px 0 6px' });
        historyHeading.append(historyTitle, deleteAll);
        const history = document.createElement('div'); history.id = 'pictos-scan-history';
        const detail = document.createElement('div'); detail.id = 'pictos-auto-results-host';
        detail.className = 'hps-scan-detail'; detail.style.display = 'none';
        overview.append(nameHeading, input, help, controls, errors, historyHeading, history);
        panel.append(overview, detail);
        return panel;
    }


    // La sélection s'applique aux prochains scans ; les relevés passés sont conservés.
    function prepareSelectionChange() {
        return allowDataChange();
    }

    function updateSelectAllButton() {
        const pictos = Array.from(document.querySelectorAll('#pictos-scanner-popup .picto-button'));
        const selected = pictos.filter(picto => picto.style.opacity !== '0.15');
        pictos.forEach(picto => picto.setAttribute('aria-pressed', String(picto.style.opacity !== '0.15')));
        const button = document.getElementById('select-all-pictos');
        if (button) button.innerText = selected.length === pictos.length ? 'Tout désélectionner' : 'Tout sélectionner';
        const total = document.getElementById('pictos-selection-count');
        if (total) total.textContent = `${selected.length}/${pictos.length} pictos sélectionnés`;
        document.querySelectorAll('#pictos-scanner-popup .category-title').forEach(category => {
            const group = pictos.filter(picto => picto.dataset.category === category.dataset.category);
            const count = group.filter(picto => picto.style.opacity !== '0.15').length;
            const complete = count === group.length;
            category.style.opacity = '1';
            category.setAttribute('aria-pressed', count === 0 ? 'false' : complete ? 'true' : 'mixed');
            category.title = `${complete ? 'Désélectionner' : 'Sélectionner'} tous les pictos : ${category.dataset.category}`;
        });
    }

    // Fonction pour sauvegarder l'état des pictos et des catégories dans scannerStorage.
    function saveSettings() {
        const pictoStates = {};
        const categoryStates = {};

        document.querySelectorAll('#pictos-scanner-popup .picto-button').forEach(picto => {
            const opacity = picto.style.opacity || '1';
            pictoStates[picto.title] = opacity;
        });

        document.querySelectorAll('#pictos-scanner-popup .category-title').forEach(categoryElement => {
            const categoryName = categoryElement.dataset.category;
            const pictos = document.querySelectorAll(`#pictos-scanner-popup .picto-button[data-category="${categoryName}"]`);
            const allDeselected = Array.from(pictos).every(picto => picto.style.opacity === '0.15');

            categoryStates[categoryName] = allDeselected ? '0.15' : '1';
        });

        const stateToSave = { pictoStates, categoryStates };
        scannerStorage.setItem('pictosState', JSON.stringify(stateToSave));
        updateSelectAllButton();
    }

    // Applique la sélection enregistrée aux pictos.
    function loadSettings(savedState) {
        document.querySelectorAll('#pictos-scanner-popup .picto-button').forEach(picto => {
            picto.style.opacity = savedState.pictoStates?.[picto.title] === '0.15' ? '0.15' : '1';
        });
        updateSelectAllButton();
    }

    // Les résultats et la progression sont sauvegardés ensemble après chaque joueur.
    function recordPlayerResult(playerId, playerName, pictosData, scanId, scanOrder) {
        const scan = getSavedScan(scanId);
        if (!scan) throw new Error('Le scan à enregistrer n’existe plus.');
        scan.results[playerId] = { playerName, pictosData, scanOrder, scannedAt: new Date().toISOString() };
    }



    // *************************************************************************************************** //
    // Fonctions de création des éléments d'interface (boutons, catégories, fenêtres)                      //
    // *************************************************************************************************** //

    // Crée un bouton de picto individuel avec son style, son icône, et ses interactions.
    function createPictoButton(picto, savedState) {
        const pictoButton = document.createElement('button');
        pictoButton.type = 'button';
        pictoButton.className = `picto-button${picto.rare ? ' hps-rare' : ''}`;
        pictoButton.setAttribute('data-picto-id', picto.id);
        pictoButton.title = picto.name;
        pictoButton.setAttribute('aria-label', picto.name);
        const pictoImage = createPictoImage(picto);
        pictoButton.appendChild(pictoImage);
        pictoButton.style.opacity = savedState.pictoStates?.[picto.name] === '0.15' ? '0.15' : '1';
        pictoButton.addEventListener('click', () => {
            if (!prepareSelectionChange()) return;
            pictoButton.style.opacity = pictoButton.style.opacity === '0.15' ? '1' : '0.15';
            saveSettings();
        });
        return pictoButton;
    }

    function createPictosSection(container, category, savedState) {
        const row = document.createElement('div');
        row.className = 'hps-selection-row';
        const categoryPictos = document.createElement('div');
        categoryPictos.className = 'hps-selection-icons';
        categoryPictos.setAttribute('role', 'group');
        categoryPictos.setAttribute('aria-label', category);
        pictoData.filter(picto => picto.category === category).forEach(picto => {
            const pictoButton = createPictoButton(picto, savedState);
            pictoButton.setAttribute('data-category', category);
            categoryPictos.appendChild(pictoButton);
        });
        row.append(createCategoryTitle(category), categoryPictos);
        container.appendChild(row);
    }

    // Crée le titre d'une catégorie avec le style et les interactions définis.
    function createCategoryTitle(category) {
        const categoryTitle = document.createElement('button');
        categoryTitle.type = 'button';
        categoryTitle.innerText = category;
        categoryTitle.classList.add('category-title');
        categoryTitle.setAttribute('data-category', category);
        categoryTitle.addEventListener('click', () => {
            if (!prepareSelectionChange()) return;
            const pictos = document.querySelectorAll(`#pictos-scanner-popup .picto-button[data-category="${category}"]`);
            const allSelected = Array.from(pictos).every(picto => picto.style.opacity !== '0.15');
            pictos.forEach(picto => {
                picto.style.opacity = allSelected ? '0.15' : '1';
            });
            saveSettings();
        });
        return categoryTitle;
    }

    // Crée le bouton principal "Pictos Scanner" avec le style et les interactions définis.
    function createMainButton() {
        const button = createCustomButton('pictos-scanner-button', 'Pictos Scanner', displayPopup);
        button.style.width = '100%';
        button.style.boxSizing = 'border-box';
        button.style.maxWidth = '100%';
        button.style.margin = '6px auto';
        return button;
    }

